options.getOption:
const sTime = context.panel.data.series[0].fields.find(f => f.type === 'time').values;
const series = context.panel.data.series[0].fields
  .filter((f) => f.type === 'number')
  .map(f =>
  ({
    name: f.name,
    type: 'bar',
    stack: 'total',
    emphasis: {
      focus: 'series'
    },
    data: f.values.map((d, i) => [sTime[i], d]),
  }));

/**
 * Enable Data Zoom by default
 */
setTimeout(() => context.panel.chart.dispatchAction({
  type: 'takeGlobalCursor',
  key: 'dataZoomSelect',
  dataZoomSelectActive: true,
}), 500);

/**
 * Update Time Range on Zoom
 */
context.panel.chart.on('datazoom', function (params) {
  const startValue = params.batch[0]?.startValue;
  const endValue = params.batch[0]?.endValue;
  locationService.partial({ from: startValue, to: endValue });
});

const res = {
  backgroundColor: 'transparent',
  tooltip: {
    trigger: 'axis',
    backgroundColor: context.grafana.theme.components.tooltip.background,
    textStyle: {
      color: context.grafana.theme.components.tooltip.text,
    },
    formatter: function (params) {
      let res = [params[0].axisValueLabel];
      res = res.concat(params
        .filter(s => s.value[1] !== null && Math.abs(s.value[1]) > 5)
        .sort((a, b) => b.value[1] - a.value[1])
        .map(s => `${s.marker} ${s.seriesName} : ${s.value[1]}`));
      return res.join('<br/>')
    }
  },
  legend: {
    left: '0',
    bottom: '0',
    data: context.panel.data.series.map(s => s.refId),
    textStyle: {
      color: 'rgba(128, 128, 128, .9)',
    },
  },
  toolbox: {
    feature: {
      dataZoom: {
        yAxisIndex: 'none',
        icon: {
          zoom: 'path://',
          back: 'path://',
        },
      },
      saveAsImage: {},
    }
  },
  xAxis: {
    type: 'time',
    data: sTime
  },
  yAxis: {
    type: 'value',
  },
  grid: {
    left: '2%',
    right: '2%',
    top: '2%',
    bottom: 24,
    containLabel: true,
  },
  series,
  animation: false
};

// console.log(res);

return res;

